import{at as e,it as t,n,vt as r}from"./chunks/framework.yntlMcNk.js";var i=JSON.parse(`{"title":"Portal","description":"","frontmatter":{"title":"Portal","covers":{"screens":["SCR-050"],"stories":[]}},"headers":[],"relativePath":"de/usage/portal.md","filePath":"de/usage/portal.md"}`),a={name:`de/usage/portal.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="portal" tabindex="-1">Portal <a class="header-anchor" href="#portal" aria-label="Permalink to “Portal”">​</a></h1><p>Das Portal zeigt die geteilten Kataloge des Repositorys nur zum Lesen. Es ist für Leute gedacht, die die Architektur lesen, aber nicht daran arbeiten, zum Beispiel mit der Rolle <code>portal-reader</code>. Alle mit der Berechtigung <code>portal:read</code> können es öffnen; die Rollen <code>viewer</code>, <code>analyst</code> und <code>enterprise-architect</code> haben sie auch.</p><h2 id="das-portal-offnen" tabindex="-1">Das Portal öffnen <a class="header-anchor" href="#das-portal-offnen" aria-label="Permalink to “Das Portal öffnen”">​</a></h2><ul><li>Mit nur <code>portal:read</code> (zum Beispiel der Rolle <code>portal-reader</code>) landest du nach der Anmeldung im Portal. Die Kopfzeile zeigt <em>Portal</em> als einzigen Eintrag; auch die Startseite und die Kataloge führen ins Portal.</li><li>Mit <code>entity:read</code> zeigt die Kopfzeile <em>Portal</em> neben <em>Kataloge</em>.</li></ul><p>Die Seite <em>Portal</em> listet die <strong>geteilten Kataloge</strong> nach Name, jeweils mit ihrem Entitätstyp. Persönliche Kataloge erscheinen nie im Portal, auch deine eigenen nicht.</p><h2 id="einen-katalog-lesen" tabindex="-1">Einen Katalog lesen <a class="header-anchor" href="#einen-katalog-lesen" aria-label="Permalink to “Einen Katalog lesen”">​</a></h2><p>Wähle einen Katalog in der Liste. Er öffnet sich mit den Spalten, der Standardsortierung und dem Standard-Join-Modus, die seine Besitzerin oder sein Besitzer eingestellt hat.</p><ul><li><strong>Sortieren:</strong> Wähle eine Spaltenüberschrift. Der erste Klick sortiert aufsteigend, der zweite absteigend, der dritte stellt die Standardreihenfolge wieder her.</li><li><strong>Blättern:</strong> Die Tabelle zeigt 50 Zeilen pro Seite; mit den Seitenzahlen unter der Tabelle wechselst du die Seite.</li><li><strong>Zurück:</strong> <em>Zurück zum Portal</em> führt zur Liste.</li></ul><p>Sortierung und Seite stehen in der Adresse, du kannst eine sortierte Seite also als Lesezeichen speichern oder weitergeben. Das Portal bietet keine Aktion, die den Katalog ändert: keine Spalten, Joins, Filter, Ansichten und keinen Navigationsbaum. Ist ein Katalog nicht mehr geteilt oder gibt es ihn nicht, zeigt die Seite <em>Katalog nicht gefunden</em>.</p><p>Das Portal zeigt wie jeder Katalog nur Eigenschaften mit der Sichtbarkeit <em>public</em>.</p><h2 id="uber-die-api" tabindex="-1">Über die API <a class="header-anchor" href="#uber-die-api" aria-label="Permalink to “Über die API”">​</a></h2><ul><li><code>GET /portal/catalogs</code> listet die geteilten Kataloge nach Name.</li><li><code>GET /portal/catalogs/{id}/query</code> liefert eine Seite eines geteilten Katalogs mit <code>page</code>, <code>pageSize</code> (höchstens 200) und <code>sort</code> (<code>{column}:{asc|desc}</code>), dasselbe Ergebnis wie <code>GET /catalogs/{id}/query</code> ohne Filter, abweichende Join-Modi oder Ansichten.</li><li>Die nächste Seite lässt sich mit <code>cursor</code> (dem <code>nextCursor</code> der vorherigen Seite) und <code>page</code> + 1 lesen, und eine Abfrage über der Zeitgrenze antwortet mit 503 <code>query-timeout</code>, wie bei der Katalogabfrage (siehe <a href="./catalogs#browse">Kataloge</a>). Ein Cursor der Katalogabfrage gilt im Portal nicht. Spalten zu Eigenschaften, die du nicht sehen darfst, sind leer, wie bei der Katalogabfrage.</li></ul><p>Beide brauchen <code>portal:read</code>. Ein persönlicher Katalog antwortet mit 404, ein ungültiger Parameter mit 400 und dem Parameter in <code>invalidFields</code>.</p>`,13)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};